css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .52); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 8%; background: repeating-linear-gradient(to bottom, #e2e8f0 0 2px, #f1f5f9 2px 32%); box-shadow: inset 0 0 0 2px #cbd5e1; }
.loader .car { position: absolute; left: 12%; width: 76%; height: 26%; border-radius: 4px; background: linear-gradient(var(--accent), var(--accent-2)); box-shadow: 0 3px 8px rgba(15, 23, 42, .28); animation: ride calc(var(--loader-speed) * 3.2) cubic-bezier(.45, 0, .35, 1) infinite; }
.loader .car::after { content: ''; position: absolute; top: 8%; left: calc(50% - 1px); width: 2px; height: 84%; background: rgba(255, 255, 255, .6); }
@keyframes ride { 0%, 10% { top: 68%; } 35%, 45% { top: 36%; } 70%, 82% { top: 4%; } 100% { top: 68%; } }
